2522	amr_dispatcher_core::dispatcher::DeadlockSnapshot DispatcherNode::BuildDeadlockSnapshot() {
2523	  // 组包逻辑下沉 core 纯函数（AssembleDeadlockSnapshot），这里只做三件事：
2524	  // 采集容器 -> 调纯函数 -> 按返回的 id 清单清扫幽灵等待者。
2525	  amr_dispatcher_core::dispatcher::DeadlockSnapshotSources sources;
2526	  sources.active_missions = active_missions_;
2527	  sources.last_progress = mission_last_progress_;
2528	  sources.reservation_acquired_at = mission_reserved_at_;
2529	  sources.pending_wait = pending_wait_;
2530	  if (reservation_table_) {
2531	    sources.reserved_resources = reservation_table_->Snapshot();
2532	  }
2533	  // 等待记录只对仍在排队的任务有效：被批量取消/离场的等待者不进 waiting_for
2534	  //（防 WFG 残留幽灵等待者；派发成功/终态路径已即时遗忘，此处兜底清扫）。
2535	  // 队列尚未建立时不做判定（与原实现 queue_ == nullptr 分支一致）。
2536	  sources.filter_stale_waiters = (queue_ != nullptr);
2537	  if (queue_) {
2538	    for (const auto& queued : queue_->SnapshotForPersistence()) {
2539	      sources.queued_mission_ids.insert(queued.id);
2540	    }
2541	  }
2542	
2543	  auto assembly = amr_dispatcher_core::dispatcher::AssembleDeadlockSnapshot(sources);
2544	  for (const auto& stale_id : assembly.stale_wait_mission_ids) {
2545	    pending_wait_.erase(stale_id);
2546	  }
2547	  return std::move(assembly.snapshot);
2548	}
