452	  // mission_id -> 派发起点（PublishState 里按直线距离折算 percent_complete）
453	  std::unordered_map<std::string, amr_dispatcher_core::path_tracking::Pose2D> mission_dispatch_start_;
454	  // mission_id -> 派发时刻（ExecuteMission result.total_duration_sec 计算用，
455	  // 终态时在 FinishExecuteGoal/CompleteMission/FailMission/取消收口里遗忘）
456	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> mission_dispatch_time_;
457	  // 导航后端：plan（默认，原 /plan 路径不变）| action（发 /navigate_sequence 单点 goal）
458	  std::string navigation_backend_{"plan"};
459	  // action 模式在途导航 goal 的归属任务与句柄（取消/终态时级联 async_cancel_goal）
460	  std::string pending_nav_mission_id_;
461	  GoalHandleNavigate::SharedPtr pending_nav_goal_handle_;
462	
463	  // Peek→Reserve→Pop：排队任务预留路由锁失败 -> 该任务仍在等的锁列表
464	  //（喂 DeadlockSnapshot.allocation_graph.waiting_for，终态/取消时遗忘）
465	  std::unordered_map<std::string, std::vector<std::string>> pending_wait_;
466	  // mission_id -> 路由锁预留成功时刻（喂 DeadlockSnapshot.reservation_acquired_at，
467	  // 长持锁启发式取证；仅任务派发预留记账，人工 ReserveResourceCb 不记，避免误报）
468	  std::unordered_map<std::string, std::chrono::steady_clock::time_point> mission_reserved_at_;
469	
470	  // ---- Task 5：逐段路权动态释放与断链安全守卫（Spec §5.2/§5.3）----
471	  // 单台受管 VDA 5050 小车的链路态（单线程 spin，无并发；M7 约束适用）
472	  // ROS 订阅句柄：只放 rclcpp 对象，生命周期随 on_cleanup/SetupVda5050Links 收口
473	  struct Vda5050LinkSubs {
474	    rclcpp::Subscription<std_msgs::msg::String>::SharedPtr state_sub;
475	    rclcpp::Subscription<std_msgs::msg::Bool>::SharedPtr online_sub;
476	  };
477	  // 两个表的 key 集合必须一致（都由 vda5050_vehicle_ids_ 驱动），
478	  // 拆开是为了让"链路纯数据"能直接喂给 core 的纯函数（守卫/选车）。
479	  std::unordered_map<std::string, Vda5050LinkSubs> vda5050_link_subs_;
480	  std::unordered_map<std::string, amr_dispatcher_core::fleet::Vda5050LinkState>
481	      vda5050_link_states_;
482	  // vehicle_id -> 隔离态集合（人工强清后置入；恢复时移除）。
483	  // 隔离车仍可见/可审计，但不参与自动分配（选车时视为不合格）。
484	  std::unordered_set<std::string> vda5050_quarantined_;
485	  // mission_id -> 派发时刻的行驶路径（travel order；Peek 阶段只留锁列表，路径在此存档，
486	  // 供 state 回推身后锁；终态经 ForgetMissionDispatchState 遗忘）
487	  std::unordered_map<std::string, std::vector<std::string>> mission_route_paths_;
488	  // mission_id -> 承接该单的受管车辆（PublishVda5050Order 下发时登记）。
489	  // 人工强清离线链路时按此反查"该车名下"的 mission —— 不能靠"路径存档存在"推断，
490	  // 那会把其他车辆的 mission 锁一并误判为该车名下（多车场景误释放）。
491	  std::unordered_map<std::string, std::string> vda5050_mission_vehicle_;
492	  // state 陈旧阈值（秒）：在线但超时未上报 -> 软看门狗告警（不释放、不阻塞）
493	  double vda5050_state_stale_sec_{5.0};
494	
495	  // ---- Task 6：VDA 5050 订单发布端（补 Task 5 评审 I2 的发布链路缺口）----
496	  // 保序受管车辆清单（SetupVda5050Links 与 vda5050_links_ 同步填充；
497	  // round-robin 绑定需要确定性顺序，unordered_map 遍历序不可依赖）
498	  std::vector<std::string> vda5050_vehicle_ids_;
499	  // vehicle_id -> send_order 发布端（on_configure 按清单一次建齐，on_activate 激活；
500	  // 网关侧订阅是懒建的，ROS 2 发布端不依赖对端存在）
501	  std::unordered_map<std::string, rclcpp_lifecycle::LifecyclePublisher<std_msgs::msg::String>::SharedPtr>
502	      vda5050_order_pubs_;
503	  // vehicle_id -> 下一单 order_update_id（同车每派一次递增，VDA 5050 更新语义）
504	  std::unordered_map<std::string, std::uint32_t> vda5050_next_order_update_id_;
505	  // round-robin 游标（按车推进；键缺失时回绕到 0）
506	  std::size_t vda5050_rr_cursor_ = 0;
507	
508	  // 12 Core Services SharedPtrs
509	  rclcpp::Service<amr_dispatcher_interfaces::srv::EnqueueMission>::SharedPtr enqueue_srv_;
510	  rclcpp::Service<amr_dispatcher_interfaces::srv::CancelQueuedMission>::SharedPtr cancel_queued_srv_;
511	  rclcpp::Service<amr_dispatcher_interfaces::srv::PreemptMission>::SharedPtr preempt_srv_;
512	  rclcpp::Service<amr_dispatcher_interfaces::srv::ReprioritizeQueuedMission>::SharedPtr reprioritize_srv_;
513	  rclcpp::Service<amr_dispatcher_interfaces::srv::EstimateMissionCost>::SharedPtr estimate_cost_srv_;
514	  rclcpp::Service<amr_dispatcher_interfaces::srv::BlockStationRoute>::SharedPtr block_route_srv_;
515	  rclcpp::Service<amr_dispatcher_interfaces::srv::DetectTrafficDeadlock>::SharedPtr detect_deadlock_srv_;
516	  rclcpp::Service<amr_dispatcher_interfaces::srv::ListStations>::SharedPtr list_stations_srv_;
517	  rclcpp::Service<amr_dispatcher_interfaces::srv::ListTrafficReservations>::SharedPtr list_reservations_srv_;
518	  rclcpp::Service<amr_dispatcher_interfaces::srv::ReserveFacilityResource>::SharedPtr reserve_facility_srv_;
519	  rclcpp::Service<amr_dispatcher_interfaces::srv::GetOperatorSnapshot>::SharedPtr snapshot_srv_;
520	  rclcpp::Service<amr_dispatcher_interfaces::srv::ValidateSiteConfig>::SharedPtr validate_site_srv_;
521	
522	  rclcpp_lifecycle::LifecyclePublisher<amr_dispatcher_interfaces::msg::DispatcherState>::SharedPtr state_pub_;
523	  rclcpp_lifecycle::LifecyclePublisher<amr_dispatcher_interfaces::msg::MissionEvent>::SharedPtr event_pub_;
524	  rclcpp_lifecycle::LifecyclePublisher<amr_dispatcher_interfaces::msg::TopologyState>::SharedPtr topology_pub_;
525	  rclcpp_lifecycle::LifecyclePublisher<nav_msgs::msg::Path>::SharedPtr plan_pub_;
526	
527	  rclcpp::Subscription<amr_dispatcher_interfaces::msg::TrackingError>::SharedPtr tracking_error_sub_;
528	  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr odom_sub_;
529	
530	  // ---- P0.6 / A4：per-vehicle 话题隔离 ----
531	  // vehicle_ids 清单（保序去重，来自参数 vehicle_ids；空 = 单车兼容模式）。
532	  std::vector<std::string> vehicle_ids_;
533	  // vehicle_id -> /plan/{vid} 发布端（on_configure 建，on_activate 激活，on_cleanup 释放）
534	  std::unordered_map<std::string, rclcpp_lifecycle::LifecyclePublisher<nav_msgs::msg::Path>::SharedPtr>
535	      vehicle_plan_pubs_;
536	  // vehicle_id -> /odom/{vid} 订阅
537	  std::unordered_map<std::string, rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr>
538	      vehicle_odom_subs_;
539	  // vehicle_id -> /tracking/error/{vid} 订阅
540	  std::unordered_map<std::string, rclcpp::Subscription<amr_dispatcher_interfaces::msg::TrackingError>::SharedPtr>
541	      vehicle_tracking_error_subs_;
542	  // vehicle_id -> 最新里程计位姿（Pose2D + has_odom 标志）。
543	  // 与 legacy 的 current_pose_/has_odom_ 并存：全局 /odom 仍只喂 legacy 字段。
544	  struct VehiclePose {
545	    amr_dispatcher_core::path_tracking::Pose2D pose{};
546	    bool has_odom = false;
547	  };
548	  std::unordered_map<std::string, VehiclePose> vehicle_poses_;
549	
550	  rclcpp::TimerBase::SharedPtr schedule_timer_;
551	  rclcpp::TimerBase::SharedPtr deadlock_timer_;
552	  rclcpp::TimerBase::SharedPtr state_timer_;
553	  rclcpp::TimerBase::SharedPtr reload_timer_;  // 1Hz 驱动站点目录 mtime 热重载
554	  rclcpp::node_interfaces::OnSetParametersCallbackHandle::SharedPtr param_callback_handle_;
555	};
556	
557	}  // namespace amr_dispatcher_ros
