3330	void DispatcherNode::PublishVda5050Order(const std::string& mission_id,
3331	                                        const std::string& assigned_vehicle_id) {
3332	  if (vda5050_vehicle_ids_.empty()) {
3333	    return;  // 未配置受管 VDA 5050 车辆：无订单发布（现网行为不变）
3334	  }
3335	  if (catalog_reloader_ == nullptr || !catalog_reloader_->loaded()) {
3336	    RCLCPP_WARN(get_logger(),
3337	                "Mission %s: station catalog not loaded, VDA 5050 order NOT published",
3338	                mission_id.c_str());
3339	    return;
3340	  }
3341	  const auto path_it = mission_route_paths_.find(mission_id);
3342	  if (path_it == mission_route_paths_.end() || path_it->second.empty()) {
3343	    RCLCPP_WARN(get_logger(),
3344	                "Mission %s: no archived travel path, VDA 5050 order NOT published",
3345	                mission_id.c_str());
3346	    return;
3347	  }
3348	  if (!reservation_table_) {
3349	    RCLCPP_WARN(get_logger(),
3350	                "Mission %s: reservation table unavailable, VDA 5050 order NOT published",
3351	                mission_id.c_str());
3352	    return;
3353	  }
3354	  // 本单名下实际持有的锁（builder 契约：严禁传全局快照——否则他人锁会被
3355	  // 误判为已放行，向小车下发未获路权的 released=true 边，违反 Spec §5.1）
3356	  // time_space 模式下本单持有的是**时空预约**（不是静态排他锁），
3357	  // 必须从时空预约表读，否则整单资源都会被判为"未获路权" -> released=false
3358	  // -> 小车在起点原地制动（observed: mock 车收到 released=[False] 的订单后不动）。
3359	  std::unordered_set<std::string> held_locks;
3360	  for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
3361	    if (owner == mission_id) {
3362	      held_locks.insert(resource_id);
3363	    }
3364	  }
3365	  for (const auto& resource_id : reservation_table_->TimeSpaceResourcesOf(mission_id)) {
3366	    held_locks.insert(resource_id);
3367	  }
3368	  // 车辆绑定：优先用选车决策给出的承接车辆（A6）；为空或不在受管清单内时
3369	  // 回落到保序清单上的 round-robin（单车配置下结果恒定，与改动前一致）。
3370	  // 判定与游标推进下沉 core 纯函数（Vda5050VehicleBindingTest 覆盖环绕/跳号）。
3371	  amr_dispatcher_core::fleet::Vda5050VehicleBindingRequest binding_req;
3372	  binding_req.assigned_vehicle_id = assigned_vehicle_id;
3373	  binding_req.managed_vehicle_ids = &vda5050_vehicle_ids_;
3374	  binding_req.round_robin_cursor = &vda5050_rr_cursor_;
3375	  const std::string vehicle_id =
3376	      amr_dispatcher_core::fleet::BindVda5050Vehicle(binding_req).vehicle_id;
3377	  const std::uint32_t update_id = vda5050_next_order_update_id_[vehicle_id]++;
3378	  const auto& catalog = catalog_reloader_->catalog();
3379	
3380	  const auto order = amr_dispatcher_core::fleet::BuildVda5050OrderFromPath(
3381	      vehicle_id, mission_id, update_id, path_it->second, catalog, held_locks);
3382	  if (!order.has_value()) {
3383	    RCLCPP_WARN(get_logger(),
3384	                "Mission %s -> vehicle %s: BuildVda5050OrderFromPath failed "
3385	                "(path %zu node(s)), VDA 5050 order NOT published",
3386	                mission_id.c_str(), vehicle_id.c_str(), path_it->second.size());
3387	    return;
3388	  }
3389	  const auto pub_it = vda5050_order_pubs_.find(vehicle_id);
3390	  if (pub_it == vda5050_order_pubs_.end() || !pub_it->second ||
3391	      !pub_it->second->is_activated()) {
3392	    RCLCPP_WARN(get_logger(),
3393	                "Mission %s -> vehicle %s: send_order publisher missing/inactive, "
3394	                "VDA 5050 order NOT published",
3395	                mission_id.c_str(), vehicle_id.c_str());
3396	    return;
3397	  }
3398	  std_msgs::msg::String out;
3399	  out.data = amr_dispatcher_core::fleet::SerializeVda5050Order(*order);
3400	  pub_it->second->publish(out);
3401	  // 登记 mission -> 车辆绑定：人工强清离线链路时据此反查"该车名下"的锁归属
3402	  vda5050_mission_vehicle_[mission_id] = vehicle_id;
3403	  RCLCPP_INFO(get_logger(),
3404	              "VDA 5050 order published: mission %s -> /fleet/%s/send_order "
3405	              "(orderId=%s, orderUpdateId=%u, %zu nodes, %zu edges, %zu bytes)",
3406	              mission_id.c_str(), vehicle_id.c_str(), order->order_id.c_str(),
3407	              update_id, order->nodes.size(), order->edges.size(), out.data.size());
3408	}
