3410	void DispatcherNode::Vda5050StateCb(const std::string& vehicle_id,
3411	                                    const std_msgs::msg::String::SharedPtr msg) {
3412	  const auto report = amr_dispatcher_core::fleet::DeserializeVda5050State(msg->data);
3413	  if (!report.has_value()) {
3414	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3415	                         "Malformed VDA 5050 state JSON from vehicle %s: %.128s",
3416	                         vehicle_id.c_str(), msg->data.c_str());
3417	    return;
3418	  }
3419	  // M1：状态报文必须与订阅话题的车辆身份一致，防止车 B 冒用车 A 的 orderId
3420	  // 驱动任务 A 的解锁流程。
3421	  if (report->vehicle_id != vehicle_id) {
3422	    RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3423	                         "VDA 5050 state identity mismatch: topic vehicle %s but "
3424	                         "serialNumber %s — dropped",
3425	                         vehicle_id.c_str(), report->vehicle_id.c_str());
3426	    return;
3427	  }
3428	  auto link_it = vda5050_link_states_.find(vehicle_id);
3429	  if (link_it != vda5050_link_states_.end()) {
3430	    // 选车输入：最近一帧的定位与电量（位置不可用 -> 该车不合格）。
3431	    // 迁移规则在 core（ApplyStateObservation）：数据照常更新，但**不改 online**。
3432	    amr_dispatcher_core::fleet::Vda5050StateObservation observation;
3433	    observation.position_initialized = report->agv_position_initialized;
3434	    observation.x = report->x;
3435	    observation.y = report->y;
3436	    observation.battery_percent = report->battery_percent;
3437	    const auto applied = amr_dispatcher_core::fleet::ApplyStateObservation(
3438	        &link_it->second, observation, std::chrono::steady_clock::now());
3439	    if (applied == amr_dispatcher_core::fleet::LinkStateApplyAction::kUpdatedWhileOffline) {
3440	      // 离线期间收到 state 绝不可回置 online=true：DDS 跨话题乱序可能把断链前
3441	      // 的最后一帧 state 排在 online=false 之后送达，若据此回置，链路会"永久
3442	      // 在线"并绕过 Spec §5.2 的调度挂起（e2e Stage 6.4 曾复现）。
3443	      // 链路存活的唯一权威判据是网关在 MQTT 有序流中确认断链之后、收到重连
3444	      // 后的新 state 或 connection=ONLINE 时重发的 online=true（网关侧见
3445	      // vda5050_gateway_node HandleState/HandleConnection）。此处仅告警：
3446	      // 锁保留、调度挂起状态均不改变；锁的解除仍由下方 Rule 1 的 lastNodeId
3447	      // 与订单一致性校验接管（不一致则全保留，Spec §5.2 位置重核对）。
3448	      RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3449	                           "VDA 5050 vehicle %s: state received while offline (locks "
3450	                           "retained, dispatch suspended) — awaiting gateway online=true "
3451	                           "re-publication after reconnect (Spec 5.2)",
3452	                           vehicle_id.c_str());
3453	    }
3454	  }
3455	  if (report->order_id.empty()) {
3456	    return;  // 无在途订单的 state（心跳/空订单）：不参与任务闭环
3457	  }
3458	  // 订单 -> 在途任务：网关订单 order_id = mission_id（BuildVda5050OrderFromPath），
3459	  // 兼容按 Mission.order_id 业务号匹配
3460	  auto mission_it = active_missions_.find(report->order_id);
3461	  if (mission_it == active_missions_.end()) {
3462	    for (auto it = active_missions_.begin(); it != active_missions_.end(); ++it) {
3463	      if (it->second.order_id == report->order_id) {
3464	        mission_it = it;
3465	        break;
3466	      }
3467	    }
3468	  }
3469	  if (mission_it == active_missions_.end()) {
3470	    return;  // 非本调度器在途任务的 state（重复/迟到/他人单）：幂等忽略，不碰锁
3471	  }
3472	  // 进度心跳：state 到达即刷新（VDA 5050 车不走 /tracking/error，
3473	  // 若不喂 progress，长距离巡航会被死锁检测判为 idle 并取消任务）。
3474	  mission_last_progress_[mission_it->first] = std::chrono::steady_clock::now();
3475	  const auto path_it = mission_route_paths_.find(mission_it->first);
3476	  if (path_it == mission_route_paths_.end() || path_it->second.empty()) {
3477	    return;  // 该单无行驶路径存档（无 pickup 等）：不参与动态解锁
3478	  }
3479	  if (!reservation_table_) {
3480	    return;  // 预约表不可用：不解锁、不判完成
3481	  }
3482	  // Rule 1（Spec §5.3）：按确认位置回推身后锁，仅释放本任务持有且已整段越过的部分
3483	  std::unordered_map<std::string, std::string> held_locks;
3484	  for (const auto& [resource_id, owner] : reservation_table_->Snapshot()) {
3485	    held_locks[resource_id] = owner;
3486	  }
3487	  const auto decision = amr_dispatcher_core::workflow::PlanTrailingUnlock(
3488	      path_it->second, report->last_node_id, report->last_node_sequence_id,
3489	      mission_it->first, held_locks);
3490	  if (!decision.confirmed) {
3491	    RCLCPP_WARN(get_logger(), "Dynamic unlock skipped (vehicle %s, order %s): %s",
3492	                vehicle_id.c_str(), report->order_id.c_str(), decision.message.c_str());
3493	    return;
3494	  }
3495	  if (!decision.lock_ids_to_release.empty()) {
3496	    const auto released = reservation_table_->ReleaseResources(mission_it->first,
3497	                                                               decision.lock_ids_to_release);
3498	    if (!released.empty()) {
3499	      std::string joined;
3500	      for (const auto& lock_id : released) {
3501	        if (!joined.empty()) joined += ",";
3502	        joined += lock_id;
3503	      }
3504	      RCLCPP_INFO(get_logger(),
3505	                  "Dynamic unlock (Spec 5.3): vehicle %s at %s -> mission %s released %zu lock(s): %s",
3506	                  vehicle_id.c_str(), report->last_node_id.c_str(), mission_it->first.c_str(),
3507	                  released.size(), joined.c_str());
3508	      // B2：窗口到期 != 资源已释放——车辆**确认驶离**该资源后才释放其时间窗，
3509	      // 否则后车会在前车还在时进入。
3510	      if (UseTimeSpaceMode()) {
3511	        ReleaseTimeSpaceForResources(mission_it->first, released);
3512	      }
3513	      if (event_log_) {
3514	        amr_dispatcher_core::dispatcher::MissionEvent evt;
3515	        evt.stamp = "now";
3516	        evt.mission_id = mission_it->first;
3517	        evt.event = "dynamic_unlock";
3518	        evt.message = "vehicle " + vehicle_id + " at " + report->last_node_id + " released " + joined;
3519	        event_log_->Append(evt);
3520	      }
3521	      ReArmQueueStartRequest();  // 唤醒排队等待这批锁的后车重试派发
3522	    }
3523	  }
3524	
3525	  // ---- VDA 5050 完成判定（评审 P0.1）----
3526	  // 外部标准协议车自带控制器，**没有** /plan 也没有 /tracking/error：
3527	  // "任务完成" = state 报文的 lastNodeId 推进到订单终点。
3528	  // 若仍用 /tracking/error 的 arrived 判完成，多车场景会张冠李戴。
3529	  // 判定放在逐段解锁**之后**：到达终点的那一帧同时要释放身后的锁（Spec §5.3）。
3530	  if (report->last_node_id != path_it->second.back()) {
3531	    return;  // 未到终点：继续在途
3532	  }
3533	  const auto bind_it = vda5050_mission_vehicle_.find(mission_it->first);
3534	  if (bind_it != vda5050_mission_vehicle_.end() && bind_it->second != vehicle_id) {
3535	    return;  // 该单绑定的是别的车：不误判完成
3536	  }
3537	  RCLCPP_INFO(get_logger(),
3538	              "VDA 5050 vehicle %s reached final node %s -> completing mission %s",
3539	              vehicle_id.c_str(), report->last_node_id.c_str(), mission_it->first.c_str());
3540	  // 原因串保持 "arrived at goal" —— 完成日志是既有可观测契约（e2e 断言依赖）。
3541	  CompleteMission(mission_it->first, "arrived at goal");
3542	}
