3544	void DispatcherNode::Vda5050OnlineCb(const std::string& vehicle_id,
3545	                                     const std_msgs::msg::Bool::SharedPtr msg) {
3546	  auto it = vda5050_link_states_.find(vehicle_id);
3547	  if (it == vda5050_link_states_.end()) {
3548	    return;
3549	  }
3550	  // 状态未变（transient_local 重放/重复报文）不重复告警——翻转判定在 core
3551	  if (!amr_dispatcher_core::fleet::ApplyOnlineReport(&it->second, msg->data)) {
3552	    return;
3553	  }
3554	  if (!msg->data) {
3555	    // Rule 2（Spec §5.2 断链锁定保护）：仅标记离线 + 软看门狗告警，绝不释放任何锁。
3556	    // 锁保留直至该车重连后 state 重核对坐标，或操作员人工强制解除。
3557	    const auto guard = amr_dispatcher_core::workflow::EvaluateVehicleLinkGuard(
3558	        /*vehicle_online=*/false, /*state_stale=*/false);
3559	    RCLCPP_WARN(get_logger(), "VDA 5050 vehicle %s link broken: %s", vehicle_id.c_str(),
3560	                guard.message.c_str());
3561	    if (event_log_) {
3562	      amr_dispatcher_core::dispatcher::MissionEvent evt;
3563	      evt.stamp = "now";
3564	      evt.mission_id = "-";  // 无任务级事件：链路级看门狗告警
3565	      evt.event = "vehicle_offline";
3566	      evt.message = "vehicle " + vehicle_id + ": retaining all route locks pending "
3567	                    "reconnection and position re-verification (Spec 5.2)";
3568	      event_log_->Append(evt);
3569	    }
3570	  } else {
3571	    RCLCPP_INFO(get_logger(),
3572	                "VDA 5050 vehicle %s back online: locks retained until state re-confirms "
3573	                "lastNodeId against the order (Spec 5.2 position re-verification)",
3574	                vehicle_id.c_str());
3575	  }
3576	}
