3578	bool DispatcherNode::EnforceVda5050LinkGuard() {
3579	  if (vda5050_link_states_.empty()) {
3580	    return false;  // 未配置受管小车：关闭状态，零开销
3581	  }
3582	  // 判定下沉 core 纯函数（隔离车跳过 / 任一离线车阻断 / stale 只告警），
3583	  // ROS 侧只做"采集 + 按判定打日志"。铁律 retain_all_locks 恒真。
3584	  amr_dispatcher_core::workflow::FleetLinkGuardRequest request;
3585	  request.state_stale_sec = vda5050_state_stale_sec_;
3586	  const auto now = std::chrono::steady_clock::now();
3587	  for (const auto& [vehicle_id, link] : vda5050_link_states_) {
3588	    amr_dispatcher_core::workflow::VehicleLinkInput input;
3589	    input.vehicle_id = vehicle_id;
3590	    input.online = link.online;
3591	    input.quarantined = link.quarantined;
3592	    input.seen_state = link.seen_state;
3593	    if (link.seen_state) {
3594	      input.state_age_sec =
3595	          std::chrono::duration_cast<std::chrono::milliseconds>(now - link.last_state_time)
3596	              .count() /
3597	          1000.0;
3598	    }
3599	    request.vehicles.push_back(std::move(input));
3600	  }
3601	  const auto decision =
3602	      amr_dispatcher_core::workflow::EvaluateFleetLinkGuard(request);
3603	  for (const auto& verdict : decision.verdicts) {
3604	    switch (verdict.kind) {
3605	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kSuspendDispatch:
3606	        // 日志文案逐字保留（e2e 直接 grep "Dispatch suspended:"）
3607	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 5000,
3608	                             "Dispatch suspended: %s (vehicle %s). On recovery the vehicle's "
3609	                             "position is re-verified via state before any lock is released.",
3610	                             verdict.message.c_str(), verdict.vehicle_id.c_str());
3611	        break;
3612	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kStaleWarning:
3613	        RCLCPP_WARN_THROTTLE(get_logger(), *get_clock(), 10000, "VDA 5050 vehicle %s: %s",
3614	                             verdict.vehicle_id.c_str(), verdict.message.c_str());
3615	        break;
3616	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kSkip:
3617	      case amr_dispatcher_core::workflow::VehicleLinkVerdict::Kind::kHealthy:
3618	        break;
3619	    }
3620	  }
3621	  return decision.block_new_dispatch;
3622	}
